## Code Example

```javascript
interface StorageProvider {
  save(ctx: any, key: string, value: any): Promise<void>;
  load(ctx: any, key: string): Promise<any>;
}
class StorageRegistry {
  private providers = new Map<string, StorageProvider>();
  register(name: string, p: StorageProvider): void { this.providers.set(name, p); }
  get(name: string): StorageProvider | undefined { return this.providers.get(name); }
